// Standalone jest config for the jitter-overlap-avoidance regression test.
const { pathsToModuleNameMapper } = require('ts-jest/utils');
const { compilerOptions } = require('../../test/ut/tsconfig');

module.exports = {
    preset: 'ts-jest',
    testEnvironment: 'jsdom',
    rootDir: '../../',
    collectCoverage: false,
    globals: {
        '__DEV__': true,
        'ts-jest': {
            tsconfig: '<rootDir>/test/ut/tsconfig.json',
            diagnostics: false,
            isolatedModules: true
        }
    },
    transformIgnorePatterns: [
        'node_modules/(?!zrender/)'
    ],
    testMatch: [
        '<rootDir>/agent_tests/jitter-overlap-avoidance/*.test.ts'
    ],
    moduleNameMapper: pathsToModuleNameMapper(compilerOptions.paths, {
        prefix: '<rootDir>/test/ut/'
    })
};

import { fixJitter } from '@/src/util/jitter';

type AxisMock = {
    model: { get: (key: string) => number | boolean },
    scale: { type: string },
    getBandWidth: () => number
};

function makeSingleAxisMock(jitter: number, margin: number = 0): AxisMock {
    // Behaves like a SingleAxis: not an Axis2D instance, non-ordinal scale,
    // so no band-width clamping is applied.
    return {
        model: {
            get(key: string) {
                if (key === 'jitter') {
                    return jitter;
                }
                if (key === 'jitterOverlap') {
                    return false;
                }
                if (key === 'jitterMargin') {
                    return margin;
                }
            }
        },
        scale: { type: 'value' },
        getBandWidth() {
            return 0;
        }
    };
}

function overlaps(
    a: { fixedCoord: number, floatCoord: number, r: number },
    b: { fixedCoord: number, floatCoord: number, r: number },
    margin: number
): boolean {
    const dx = a.fixedCoord - b.fixedCoord;
    const dy = a.floatCoord - b.floatCoord;
    const r = a.r + b.r + margin;
    return dx * dx + dy * dy < r * r - 1e-6;
}

describe('jitter overlap avoidance', function () {

    it('should not overlap when there is enough space to avoid', function () {
        // Mirror of the upstream special case (apache/echarts#21067 follow-up):
        // many points on the same fixed coord, large jitter budget.
        const jitter = 500;
        const radius = 15;
        const axis = makeSingleAxisMock(jitter) as any;

        // Clustered float coords, all with the same fixedCoord.
        const floatCoords = [
            11.2, 10.7, 11.4, 11.8, 11.5, 10, 10.3, 11.1, 11.2, 11.8,
            10.7, 11, 11.1, 11.7, 10.5, 10.9, 11.2, 10.4, 11.6, 10.1,
            11.1, 11.8, 11.3, 10.8, 10.5, 10.5, 10.8, 10.3, 10.6, 10.2
        ];

        const placed: { fixedCoord: number, floatCoord: number, r: number }[] = [];
        for (let i = 0; i < floatCoords.length; i++) {
            const fixedCoord = 0;
            const result = fixJitter(axis, fixedCoord, floatCoords[i], radius);
            // Adjusted point must stay within the jitter budget.
            expect(Math.abs(result - floatCoords[i])).toBeLessThanOrEqual(jitter / 2 + 1e-6);
            const item = { fixedCoord, floatCoord: result, r: radius };
            // Must not overlap any previously placed point — space is ample.
            for (let j = 0; j < placed.length; j++) {
                expect(overlaps(item, placed[j], 0)).toBe(false);
            }
            placed.push(item);
        }
    });

    it('should place points on both sides without overlap', function () {
        // Regression: old linked-list implementation missed existing items
        // on one side once items were inserted in mixed directions.
        const jitter = 200;
        const radius = 10;
        const axis = makeSingleAxisMock(jitter) as any;

        const placed: { fixedCoord: number, floatCoord: number, r: number }[] = [];
        for (let i = 0; i < 12; i++) {
            const fixedCoord = 0;
            const result = fixJitter(axis, fixedCoord, 0, radius);
            expect(Math.abs(result)).toBeLessThanOrEqual(jitter / 2 + 1e-6);
            const item = { fixedCoord, floatCoord: result, r: radius };
            for (let j = 0; j < placed.length; j++) {
                expect(overlaps(item, placed[j], 0)).toBe(false);
            }
            placed.push(item);
        }
    });

    it('should fall back within jitter budget when space is exhausted', function () {
        // jitter too small to fit all points: result must still respect
        // the jitter budget (random fallback stays within jitter / 2).
        const jitter = 30;
        const radius = 10;
        const axis = makeSingleAxisMock(jitter) as any;

        for (let i = 0; i < 10; i++) {
            const result = fixJitter(axis, 0, 0, radius);
            expect(Math.abs(result)).toBeLessThanOrEqual(jitter / 2 + 1e-6);
        }
    });
});

